/* cppi::be1505a1c79017763734e5f3a55572bf1867c04e8bb1181f3115f6bbda70bbbc */
select distinct request_id, start_date, end_date, pool, strategy_alternative, weight, start_date as business_date
from performance.tpm_tpm_atp_weights where request_id = 
(select max(request_id) from performance.tpm_tpm_atp_weights where start_date = '2025-04-09' and end_date = '2025-04-09')
and start_date = '2025-04-09' and end_date = '2025-04-09'

